export const SUPPLEMENTAL_MOVIES: MovieEntry[] = RAW_MOVIES.map(
  ([id, directorId, title, year, cast, label, significance, rawSongs]) => ({
    id,
    directorId,
    title,
    year,
    ...(cast ? { cast } : {}),
    ...(label ? { label } : {}),
    ...(significance ? { significance } : {}),
    songs: rawSongs.map(([sid, stitle, singers, ref, lyricist]): SongEntry => ({
      id: sid,
      movieId: id,
      title: stitle,
      singers,
      ...(lyricist ? { lyricist } : {}),
      adaptationType: 'original',
      originCategory: 'Original Composition',
      bollywoodLink: '',
      referenceSource: typeof ref === 'number' ? REF_MAP[ref] : ref,
    })),
  })
);
